const KEYS = { progress:"hsc-tracker-progress-v1", preferences:"hsc-tracker-preferences-v1", sessions:"hsc-tracker-sessions-v1", weak:"hsc-tracker-weak-v1", timer:"hsc-tracker-active-session-v1", revisions:"hsc-tracker-revisions-v1", progressHistory:"hsc-tracker-progress-history-v1" };
const themes = [["dark","Dark","#10131b"],["light","Light","#f4f6f8"],["forest","Forest green","#10211d"],["violet","Midnight violet","#191426"],["blue","Dark blue","#101b2b"]];
const todayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch(error){console.warn("Could not save",key,error)}};
const makeId=()=>globalThis.crypto&&globalThis.crypto.randomUUID?globalThis.crypto.randomUUID():`s-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;
const normalizeSession=s=>({...s,date:s.date||todayKey(new Date(s.startedAt||Date.now())),minutes:Number(s.minutes)||0});
// Reads sessions from storage and drops any repeated session id, so one saved session is only ever counted once.
function loadSessions(){const seen=new Set(),out=[];
for(const raw of read(KEYS.sessions,[])){const s=normalizeSession(raw);
if(s.id){if(seen.has(s.id))continue;
seen.add(s.id)}out.push(s)}return out}// The only way a session is saved. Re-reads storage first and refuses an id that already exists.
function addSession(session){const current=loadSessions();
if(current.some(s=>s.id===session.id)){state.sessions=current;
return false}current.push(normalizeSession(session));
save(KEYS.sessions,current);
state.sessions=current;
return true}const state={progress:read(KEYS.progress,{}),preferences:read(KEYS.preferences,{theme:"dark",goal:240,targets:{},language:"en"}),sessions:loadSessions(),weak:read(KEYS.weak,[]),timerData:read(KEYS.timer,null),revisions:read(KEYS.revisions,[]),progressHistory:read(KEYS.progressHistory,[]),subjects:Array.isArray(window.HSC_SUBJECTS)?window.HSC_SUBJECTS:[],page:"overview",syllabusSubject:null,syllabusPaper:null,syllabusGroup:"science",historyMode:"daily",reviewMonth:new Date().getMonth(),tick:null,lastManualAt:0};
state.preferences.language=state.preferences.language==="bn"?"bn":"en";
state.syllabusGroup=["science","business","humanities"].includes(state.preferences.group)?state.preferences.group:"science";
// Active timer sessions are temporary. Never restore an abandoned session on a fresh page load.
if(state.timerData){state.timerData=null;try{localStorage.removeItem(KEYS.timer)}catch{}}
function discardActiveTimer(){if(!state.timerData)return;
state.timerData=null;
clearInterval(state.tick);
state.tick=null;
try{localStorage.removeItem(KEYS.timer)}catch{}}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")render()});
window.addEventListener("pagehide",discardActiveTimer);
const plural=(n,word)=>n===1?word:word+"s";
const locale=()=>state.preferences.language==="bn"?"bn-BD":"en-US";
const subjectName=s=>state.preferences.language==="bn"?s.name.bn:s.name.en;
const chapterName=c=>state.preferences.language==="bn"?c.name.bn:c.name.en;
